{
  "contract": "ReservaX",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "withdraw",
      "earlyPurchase",
      "publicPurchase",
      "setWindows",
      "setMaxEarly",
      "setMaxPublic",
      "setMaxSupply",
      "pauseContract",
      "newCost",
      "setLevels",
      "setAmounts",
      "setAddresses",
      "setCreators"
    ],
    "justification": "The functions included in the closure either directly affect storage variables exposed during the 'withdraw' function or are public/external functions that can be used for re-entry."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "earlyPurchase",
      "publicPurchase",
      "setWindows",
      "setMaxEarly",
      "setMaxPublic",
      "setMaxSupply",
      "pauseContract",
      "newCost",
      "setLevels",
      "setAmounts",
      "setAddresses",
      "setCreators"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "pre:before_transfer",
      "to_marker": "exposed:start"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "exposed:start",
      "to_marker": "post:after_transfer"
    },
    "post": {
      "name": "post",
      "from_marker": "post:after_transfer",
      "to_marker": "post:end"
    },
    "linearization_point": "post:after_transfer"
  },
  "ghost_state": [
    {
      "name": "inFlightNine",
      "sol_type": "uint256",
      "meaning": "tracks the in-flight withdrawals for asset nine during the exposed phase",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "withdrawNine == _totalSupply[9] + inFlightNine",
    "stable_formula": "withdrawNine == _totalSupply[9]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "withdrawNine <= _totalSupply[9] && withdrawTen <= _totalSupply[10]",
    "rule": "Exposure invariants are preserved across callbacks and the final state complies with the target property."
  }
}
